'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var isAlmostEqual = require( '@stdlib/assert/is-almost-equal-float64array' );
var dlasrt = require( './../lib/dlasrt.js' );


// FIXTURES //

var N_LT_20_INC = require( './fixtures/n_lt_20_inc.json' );
var N_LT_20_DEC = require( './fixtures/n_lt_20_dec.json' );
var N_GT_20_INC = require( './fixtures/n_gt_20_inc.json' );
var N_GT_20_INC_1 = require( './fixtures/n_gt_20_inc_1.json' );
var N_GT_20_INC_2 = require( './fixtures/n_gt_20_inc_2.json' );
var N_GT_20_INC_3 = require( './fixtures/n_gt_20_inc_3.json' );
var N_GT_20_INC_4 = require( './fixtures/n_gt_20_inc_4.json' );
var N_GT_20_INC_5 = require( './fixtures/n_gt_20_inc_5.json' );
var N_GT_20_DEC = require( './fixtures/n_gt_20_dec.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlasrt, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 3', function test( t ) {
	t.strictEqual( dlasrt.length, 3, 'returns expected value' );
	t.end();
});

tape( 'the function quick returns when provided wrong inputs', function test( t ) {
	var out;
	var D;

	D = new Float64Array( 6 );

	out = dlasrt( 'foo', 6, D );
	t.strictEqual( out, -1, 'returns expected value' );

	D = new Float64Array( 6 );

	out = dlasrt( 'I', -1, D );
	t.strictEqual( out, -2, 'returns expected value' );

	D = new Float64Array( 6 );

	out = dlasrt( 'I', 0, D );
	t.strictEqual( out, 0, 'returns expected value' );
	t.end();
});

tape( 'the function sorts a double-precision floating-point strided array in increasing or decreasing order (N<20)', function test( t ) {
	var expected;
	var data;
	var D;

	data = N_LT_20_INC;

	D = new Float64Array( data.D );
	expected = new Float64Array( data.D_out );

	dlasrt( data.sortOrder, data.N, D );
	t.strictEqual( isAlmostEqual( D, expected, 1 ), true, 'returns expected value' );

	data = N_LT_20_DEC;

	D = new Float64Array( data.D );
	expected = new Float64Array( data.D_out );

	dlasrt( data.sortOrder, data.N, D );
	t.strictEqual( isAlmostEqual( D, expected, 1 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function sorts a double-precision floating-point strided array in increasing or decreasing order (N>20)', function test( t ) {
	var expected;
	var data;
	var D;

	data = N_GT_20_DEC;

	D = new Float64Array( data.D );
	expected = new Float64Array( data.D_out );

	dlasrt( data.sortOrder, data.N, D );
	t.strictEqual( isAlmostEqual( D, expected, 1 ), true, 'returns expected value' );

	data = N_GT_20_INC;

	D = new Float64Array( data.D );
	expected = new Float64Array( data.D_out );

	dlasrt( data.sortOrder, data.N, D );
	t.strictEqual( isAlmostEqual( D, expected, 1 ), true, 'returns expected value' );

	data = N_GT_20_INC_1;

	D = new Float64Array( data.D );
	expected = new Float64Array( data.D_out );

	dlasrt( data.sortOrder, data.N, D );
	t.strictEqual( isAlmostEqual( D, expected, 1 ), true, 'returns expected value' );

	data = N_GT_20_INC_2;

	D = new Float64Array( data.D );
	expected = new Float64Array( data.D_out );

	dlasrt( data.sortOrder, data.N, D );
	t.strictEqual( isAlmostEqual( D, expected, 1 ), true, 'returns expected value' );

	data = N_GT_20_INC_3;

	D = new Float64Array( data.D );
	expected = new Float64Array( data.D_out );

	dlasrt( data.sortOrder, data.N, D );
	t.strictEqual( isAlmostEqual( D, expected, 1 ), true, 'returns expected value' );

	data = N_GT_20_INC_4;

	D = new Float64Array( data.D );
	expected = new Float64Array( data.D_out );

	dlasrt( data.sortOrder, data.N, D );
	t.strictEqual( isAlmostEqual( D, expected, 1 ), true, 'returns expected value' );

	data = N_GT_20_INC_5;

	D = new Float64Array( data.D );
	expected = new Float64Array( data.D_out );

	dlasrt( data.sortOrder, data.N, D );
	t.strictEqual( isAlmostEqual( D, expected, 1 ), true, 'returns expected value' );
	t.end();
});
